export type OrderCreateRequest =
  | {
      /**
       * 클라이언트 지정 주문 식별자. 멱등성 키로 사용됩니다.
       * - 미전달: 멱등성 미적용. 매 요청을 별개 주문으로 처리합니다.
       * - 전달: 동일 값으로 재요청 시 이전 주문 결과를 그대로 재반환합니다.
       * 서버는 자동 생성하지 않습니다.
       * 최대 36자, 영숫자 및 `-`, `_` 허용.
       * 멱등성 키는 10분간 유효하며, 이후 동일 값으로 재요청 시 새 주문으로 처리됩니다.
       *
       */
      clientOrderId?: string;
      /**
       * 종목 심볼. KRX: 6자리 종목코드 (숫자 또는 영문·숫자 조합), US: 영문 티커
       */
      symbol: string;
      /**
       * 주문 방향
       */
      side: 'BUY' | 'SELL';
      /**
       * 호가 유형.
       * - `LIMIT`: 지정가
       * - `MARKET`: 시장가
       *
       */
      orderType: 'LIMIT' | 'MARKET';
      /**
       * 주문 유효 조건 (Time In Force). 미전달 시 `DAY`. `orderType` 과 결합되어 주문 방식이 결정됩니다 (예: `LIMIT` + `CLS` = LOC).
       * - `DAY`: 당일 유효 (Day). 정규장 종료까지 미체결분은 자동 취소됩니다.
       * - `CLS`: 장 마감 주문 (At the Close). 현재 미국 주식 + `orderType=LIMIT` 조합만 지원합니다.
       * - `OPG`: 장 개시 주문 (At the Opening, 국내 시가단일가). 현재 국내 주식 전용이며 `orderType` 은 `LIMIT`/`MARKET` 모두 지원합니다. 세션 시간(장전 사전접수) 외 접수는 원장에서 거절될 수 있습니다.
       *
       */
      timeInForce?: 'DAY' | 'CLS' | 'OPG';
      /**
       * 주문 수량 (주 단위). 지정한 수량만큼 주문합니다.
       * - 기본: 양의 정수만 가능합니다.
       * - 소수점 수량: 미국 주식 시장가 매도(`orderType=MARKET` + `side=SELL`) 주문에만 허용됩니다.
       * 그 외(매수/지정가/국내) 소수점 수량은 `400 invalid-request` 를 반환합니다.
       * 소수점 매수는 `orderAmount` 를 사용하세요.
       * 소수점 수량 매도는 정규장 시작부터 정규장 종료 1시간 전까지만 접수 가능하며, 그 외 시간 요청 시 `422 fractional-quantity-outside-regular-hours` 를 반환합니다.
       * 소수점 수량은 소수점 6자리까지 지원하며, 초과 시 `400 invalid-request` (`fractional-quantity-scale-exceeded`) 를 반환합니다.
       *
       */
      quantity: string;
      /**
       * 주문 가격. `orderType`이 `LIMIT` 일 때만 사용합니다.
       * - `LIMIT`: 필수. 미전달 시 `400 invalid-request`.
       * - `MARKET`: 전달 불가. 전달 시 `400 invalid-request`.
       * - KR: 정수 (원 단위). 호가 단위에 맞아야 합니다 (예: 50,000~200,000원 구간은 100원 단위). 맞지 않으면 `400 invalid-request` 에러와 함께 올바른 호가 단위가 `data`에 포함됩니다.
       * - US: 소수점 (달러 단위).
       * - $1 미만: 소수점 넷째 자리까지 (그 이하 자릿수는 절삭).
       * - $1 이상: 소수점 둘째 자리까지 (그 이하 자릿수는 절삭).
       *
       */
      price?: string;
      /**
       * 착오주문 방지를 위한 주문 확인 플래그. 기본값 `false`.
       * 1억원 이상의 주문 시 `true`가 아니면 `400 confirm-high-value-required` 에러를 반환합니다.
       * 사용자가 해당 주문의 금액을 인지하고 있음을 표시하기 위한 필드입니다.
       *
       */
      confirmHighValueOrder?: boolean;
    }
  | {
      /**
       * 클라이언트 지정 주문 식별자. 멱등성 키로 사용됩니다.
       * - 미전달: 멱등성 미적용. 매 요청을 별개 주문으로 처리합니다.
       * - 전달: 동일 값으로 재요청 시 이전 주문 결과를 그대로 재반환합니다.
       * 서버는 자동 생성하지 않습니다.
       * 최대 36자, 영숫자 및 `-`, `_` 허용.
       * 멱등성 키는 10분간 유효하며, 이후 동일 값으로 재요청 시 새 주문으로 처리됩니다.
       *
       */
      clientOrderId?: string;
      /**
       * US 종목 심볼 (영문 티커). 금액 기반 주문은 US MARKET 전용입니다.
       */
      symbol: string;
      /**
       * 주문 방향
       */
      side: 'BUY' | 'SELL';
      /**
       * 호가 유형. 금액 기반 주문은 `MARKET` 만 허용합니다.
       */
      orderType: 'MARKET';
      /**
       * 주문 금액 (달러). 지정한 금액만큼 주문합니다.
       * 체결 수량은 체결 시점의 시장가에 따라 결정됩니다.
       *
       * Quantity-based 와의 차이: quantity 는 수량을 확정하고 비용이 변동하며,
       * orderAmount 는 금액을 확정하고 수량이 변동합니다.
       *
       * 정규장 시작부터 정규장 종료 1시간 전까지만 접수 가능합니다.
       * 그 외 시간 요청 시 `422 amount-order-outside-regular-hours` 에러를 반환합니다.
       *
       */
      orderAmount: string;
      /**
       * 착오주문 방지를 위한 주문 확인 플래그. 기본값 `false`.
       * 1억원 이상의 주문 시 `true`가 아니면 `400 confirm-high-value-required` 에러를 반환합니다.
       * 사용자가 해당 주문의 금액을 인지하고 있음을 표시하기 위한 필드입니다.
       *
       */
      confirmHighValueOrder?: boolean;
    };

export type OrderModifyRequest = {
  /**
   * 변경할 호가 유형.
   * - `LIMIT`: 지정가
   * - `MARKET`: 시장가
   *
   */
  orderType: 'LIMIT' | 'MARKET';
  /**
   * 변경할 수량.
   * **KR 주식: 필수.** 양의 정수만 허용합니다 (미전달/0/음수/소수점은 `400 invalid-request`).
   * US 주식: 전달 불가. 제공 시 `400 us-modify-quantity-not-supported` 에러.
   *
   */
  quantity?: string;
  /**
   * 변경할 가격. `orderType`이 `LIMIT` 일 때만 사용합니다.
   * - `LIMIT`: 필수. 미전달 시 `400 invalid-request`.
   * - `MARKET`: 전달 불가. 전달 시 `400 invalid-request`.
   * - KR: 정수 (원 단위). 호가 단위에 맞아야 합니다. 맞지 않으면 `400 invalid-request` 에러.
   * - US: 소수점 (달러 단위).
   * - $1 미만: 소수점 넷째 자리까지 (그 이하 자릿수는 절삭).
   * - $1 이상: 소수점 둘째 자리까지 (그 이하 자릿수는 절삭).
   *
   */
  price?: string;
  /**
   * 착오주문 방지를 위한 주문 확인 플래그. 기본값 `false`.
   * 1억원 이상의 주문 시 `true`가 아니면 `400 confirm-high-value-required` 에러를 반환합니다.
   * 사용자가 해당 주문의 금액을 인지하고 있음을 표시하기 위한 필드입니다.
   * 30억원 이상의 주문은 본 플래그와 무관하게 `422 max-order-amount-exceeded` 에러를 반환합니다.
   *
   */
  confirmHighValueOrder?: boolean;
};

export type OrderResponse = {
  /**
   * 서버 생성 주문 식별자. 정정/취소 시 사용
   */
  orderId: string;
  /**
   * 요청 시 전달한 값 그대로 반환. 미전달 시 `null`.
   */
  clientOrderId?: string | null;
};

export type OrderOperationResponse = {
  /**
   * 정정/취소로 새로 발급된 주문 식별자. 원주문의 orderId 와 다릅니다.
   *
   */
  orderId: string;
};

/**
 * 조건주문 생성 요청. "이 가격(triggerPrice)에 닿으면 매수/매도(orderSide) 주문" 만 입력하면 됩니다.
 * 가격이 감시가(triggerPrice)에 닿으면 트리거됩니다.
 * 타입은 `type`(SINGLE/OCO/OTO)으로 지정합니다.
 *
 */
export type ConditionalOrderCreateRequest = {
  /**
   * 종목 심볼. KRX: 6자리 종목코드 (숫자 또는 영문·숫자 조합), US: 영문 티커
   */
  symbol: string;
  /**
   * 조건주문 타입 (조건의 개수와 관계).
   * - `SINGLE`: 한 조건만 감시
   * - `OCO` (One-Cancels-the-Other): 두 조건을 동시에 감시, 하나의 조건 충족 시 나머지 조건 자동 취소
   * - `OTO` (One-Triggers-the-Other): `first` 조건 체결 후 `second` 조건 감시 시작
   *
   */
  type: 'SINGLE' | 'OCO' | 'OTO';
  /**
   * 매매 수량 (주 단위). 조건주문 그룹 공통값 — OCO/OTO 는 동일 포지션이라 first/second 가 같은 수량을 씁니다.
   */
  quantity: string;
  /**
   * 호가유형 (그룹 공통). `LIMIT`(지정가) 이면 각 조건의 `orderPrice` 가 필수이고, `MARKET`(시장가) 이면 `orderPrice` 를 지정할 수 없습니다.
   * OCO/OTO 는 지정가(`LIMIT`)만 지원합니다.
   *
   */
  orderType: 'LIMIT' | 'MARKET';
  /**
   * 멱등키 (선택) — 주문 생성 API 와 동일. 동일한 값으로 재요청 시 중복 생성을 방지합니다.
   */
  clientOrderId?: string;
  /**
   * 조건주문 만료일 (YYYY-MM-DD, 필수). 오늘로부터 최대 1년까지 지정할 수 있습니다. 만료일까지 조건이 충족되지 않으면 자동 만료됩니다.
   */
  expireDate: string;
  /**
   * 첫번째 감시 조건 (필수). OTO 는 먼저 감시할 부모 조건입니다.
   */
  first: ConditionRequest;
  /**
   * 두번째 감시 조건. SINGLE 은 생략(설정하지 않음), OCO/OTO 는 필수. 그 외 구조·규칙은 first 와 동일합니다.
   */
  second?: ConditionRequest;
  /**
   * 1억원 이상 주문 동의 여부
   */
  confirmHighValueOrder?: boolean;
};

/**
 * 조건주문 수정 요청. 등록과 동일하게 "이 가격에 닿으면 매매" 만 입력하며,
 * 조건주문 전체를 재설정하므로 유지할 조건도 함께 전달해야 합니다.
 * 종목은 `conditionalOrderId` 로 식별되므로 수정 요청에는 `symbol` 이 필요 없습니다.
 *
 */
export type ConditionalOrderModifyRequest = {
  /**
   * 변경 결과 타입. 수정 시 타입 전환(예: SINGLE→OCO)이 허용됩니다.
   *
   */
  type: 'SINGLE' | 'OCO' | 'OTO';
  /**
   * 매매 수량 (주 단위, 그룹 공통).
   */
  quantity: string;
  /**
   * 호가유형 (그룹 공통). LIMIT(지정가)/MARKET(시장가). OCO/OTO 는 지정가만 지원합니다.
   */
  orderType: 'LIMIT' | 'MARKET';
  /**
   * 조건주문 만료일 (수정 시 필수). 오늘로부터 최대 1년까지 지정할 수 있습니다.
   */
  expireDate: string;
  /**
   * 첫번째 감시 조건 (필수). OTO 는 먼저 감시할 부모 조건입니다.
   */
  first: ConditionRequest;
  /**
   * 두번째 감시 조건. SINGLE 은 생략(설정하지 않음), OCO/OTO 는 필수. 그 외 구조·규칙은 first 와 동일합니다.
   */
  second?: ConditionRequest;
  /**
   * 1억원 이상 주문 동의 여부
   */
  confirmHighValueOrder?: boolean;
};

/**
 * 감시 조건 (leg). 가격이 `triggerPrice` 에 닿으면 `orderSide`(매수/매도) 주문을 냅니다.
 * 수량(`quantity`)·호가유형(`orderType`)은 그룹 공통이라 상위 요청에 있습니다.
 * 호가유형이 `LIMIT` 이면 `orderPrice` 가 필수이고, `MARKET` 이면 `orderPrice` 를 보내면 안 됩니다.
 * `orderPrice` 는 호가 단위에 맞아야 하며, 맞지 않으면 `400 invalid-request` 에러와 함께 올바른 호가 단위가 `data`에 포함됩니다.
 *
 */
export type ConditionRequest = {
  /**
   * 매매 유형 (매수/매도)
   */
  orderSide: 'BUY' | 'SELL';
  /**
   * 감시 가격. 현재가가 이 값에 닿으면 주문을 생성합니다.
   */
  triggerPrice: string;
  /**
   * [orderType=LIMIT] 주문 가격(지정가). 트리거 시 이 가격의 지정가 주문을 생성합니다. MARKET 이면 보내지 않습니다.
   * - KR: 정수 (원 단위). 호가 단위에 맞아야 합니다 (예: 50,000~200,000원 구간은 100원 단위).
   * - US: 소수점 (달러 단위). 호가 단위에 맞아야 합니다 ($1 미만은 0.0001, $1 이상은 0.01 단위).
   *
   * 호가 단위에 맞지 않으면 `400 invalid-request` 에러와 함께 올바른 호가 단위가 `data`에 포함됩니다.
   *
   */
  orderPrice?: string;
};

/**
 * 조건주문 수정·취소 응답. 대상 조건주문 식별자만 반환합니다.
 */
export type ConditionalOrderResponse = {
  /**
   * 조건주문 식별자
   */
  conditionalOrderId: string;
};

export type PaginatedConditionalOrderResponse = {
  conditionalOrders: Array<ConditionalOrderDetailResponse>;
  /**
   * 다음 페이지 커서. 마지막 페이지면 null.
   */
  nextCursor?: string | null;
  /**
   * 다음 페이지 존재 여부
   */
  hasNext: boolean;
};

/**
 * 조건주문 조회 응답 (목록 항목 / 상세 공용). 모든 타입을 단일 스키마로 표현하며,
 * 감시 조건은 `first`/`second` 로 내려갑니다 (SINGLE 은 `first` 만, OCO/OTO 는 `second` 도 존재).
 *
 */
export type ConditionalOrderDetailResponse = {
  /**
   * 조건주문 식별자. 상세 조회·수정·취소에 사용합니다.
   *
   */
  conditionalOrderId: string;
  /**
   * 조건주문 타입.
   * - `SINGLE`: 한 조건만 감시
   * - `OCO` (One-Cancels-the-Other): 두 조건을 동시에 감시, 하나의 조건 충족 시 나머지 조건 자동 취소
   * - `OTO` (One-Triggers-the-Other): `first` 조건 체결 후 `second` 조건 감시 시작
   *
   */
  type: 'SINGLE' | 'OCO' | 'OTO';
  /**
   * 조건주문(그룹) 상태 — 살아있는 조건(leg)의 상태를 대표로 따릅니다.
   * leg 전용 상태인 `HOLDING`·`CANCELED` 는 최상위 status 로는 내려오지 않습니다 (조건별 상태 `first.status`/`second.status` 에서만 노출).
   * - `WATCHING`: 조건 감시 중
   * - `PAUSED`: 일시중지
   * - `ORDERING`: 조건 충족 — 주문 생성 진행 중
   * - `ORDERED`: 주문 생성됨
   * - `COMPLETED`: 완료
   * - `EXPIRED`: 만료
   *
   */
  status: 'WATCHING' | 'PAUSED' | 'ORDERING' | 'ORDERED' | 'COMPLETED' | 'EXPIRED';
  /**
   * 종목 심볼. KRX: 6자리 종목코드 (숫자 또는 영문·숫자 조합), US: 영문 티커
   */
  symbol: string;
  /**
   * 시장 구분
   */
  market: 'KR' | 'US';
  /**
   * 매매 수량 (주 단위, 그룹 공통).
   */
  quantity: string;
  /**
   * 호가유형 (그룹 공통). LIMIT(지정가)/MARKET(시장가).
   */
  orderType: 'LIMIT' | 'MARKET';
  /**
   * 조건주문 만료일 (조건주문 1건의 모든 감시 조건이 공유). 이 날짜까지 미충족 시 자동 만료됩니다.
   */
  expireDate?: string;
  /**
   * 첫번째 감시 조건 (OTO 는 부모)
   */
  first: ConditionalOrderCondition;
  /**
   * 두번째 감시 조건. OCO/OTO 만 존재하며 단일(SINGLE)은 null.
   */
  second?: ConditionalOrderCondition;
  /**
   * 조건주문 등록 시각 (KST)
   */
  createdAt: string;
};

export type ConditionalOrderCondition = {
  /**
   * 감시 조건 세부 타입 (그룹 타입을 구성하는 단위).
   * - `STOP`: 가격 트리거
   * - `PROFIT_RATE`: 목표 수익률(%) 트리거
   *
   * 그룹(OCO/OTO)의 `first` 와 `second` 는 항상 동일한 타입입니다.
   *
   */
  type: 'STOP' | 'PROFIT_RATE';
  /**
   * 조건(leg) 단위 상태. 최상위 조건주문 `status` 와 달리 leg 전용인 `HOLDING`·`CANCELED` 를 포함합니다.
   * - `HOLDING`: 선행 조건(OTO first) 체결 전 대기 (leg 전용)
   * - `CANCELED`: 취소됨 (완료된 OCO 에서 자동취소된 반대편 조건)
   *
   */
  status:
    | 'WATCHING'
    | 'HOLDING'
    | 'PAUSED'
    | 'ORDERING'
    | 'ORDERED'
    | 'COMPLETED'
    | 'EXPIRED'
    | 'CANCELED';
  /**
   * 매매 유형 (매수/매도). 조건 충족 시 이 유형으로 주문을 냅니다. 등록 요청의 `orderSide` 와 같은 값입니다.
   */
  orderSide: 'BUY' | 'SELL';
  /**
   * 이 가격에 닿으면 트리거됩니다.
   * 현재 지원 조건은 항상 값이 존재하나, 향후 수익률(PROFIT_RATE)·추종형 조건은 고정 트리거가가 없어 null 일 수 있습니다.
   *
   */
  triggerPrice?: string | null;
  /**
   * [PROFIT_RATE 전용] 감시 수익률. **퍼센트(%) 단위**입니다 (예: `10.5` = +10.5%).
   * PROFIT_RATE 이 아닌 조건이면 null.
   *
   */
  targetProfitRate?: string | null;
  /**
   * 주문 가격(지정가). 그룹 호가유형(orderType)이 LIMIT 이면 값이 있고, MARKET 이면 null.
   */
  orderPrice?: string | null;
  /**
   * 조건 충족으로 생성된 주문의 ID. 일반 주문 API(`GET /orders/{orderId}` 등)에 그대로 사용할 수 있습니다. 주문 생성 전이면 null.
   *
   */
  triggeredOrderId?: string | null;
};

/**
 * 주문 목록 페이징 응답.
 * - `status=OPEN`: 모든 대기 중 주문을 반환합니다. `nextCursor`는 항상 `null`, `hasNext`는 항상 `false`.
 * - `status=CLOSED`: `limit` 단위로 페이징합니다. 다음 페이지가 있으면 `nextCursor`에 커서가, `hasNext`에 `true`가 내려옵니다.
 *
 */
export type PaginatedOrderResponse = {
  /**
   * 주문 목록
   */
  orders: Array<Order>;
  /**
   * 다음 페이지 커서. 다음 페이지가 없으면 null
   */
  nextCursor: string | null;
  /**
   * 다음 페이지 존재 여부
   */
  hasNext: boolean;
};

export type Order = {
  /**
   * 주문 식별자
   */
  orderId: string;
  /**
   * 종목 심볼. KRX: 6자리 종목코드 (숫자 또는 영문·숫자 조합), US: 영문 티커
   */
  symbol: string;
  /**
   * 주문 방향
   */
  side: 'BUY' | 'SELL';
  /**
   * 호가 유형.
   * - `LIMIT`: 지정가
   * - `MARKET`: 시장가
   *
   * 클라이언트는 unknown code 를 허용하도록 구현해야 합니다.
   *
   */
  orderType: 'LIMIT' | 'MARKET';
  /**
   * 주문 유효 조건 (Time In Force). `orderType` 과 결합되어 주문 방식이 결정됩니다 (예: `LIMIT` + `CLS` = LOC).
   * - `DAY`: 당일 유효 (Day)
   * - `CLS`: 장 마감 주문 (At the Close)
   * - `OPG`: 장 개시 주문 (At the Opening, 국내 시가단일가)
   *
   * 클라이언트는 unknown code 를 허용하도록 구현해야 합니다.
   *
   */
  timeInForce: 'DAY' | 'CLS' | 'OPG';
  status: OrderStatus;
  /**
   * 주문 가격 (native currency). MARKET 주문 시 null
   */
  price?: string | null;
  /**
   * 주문 수량
   */
  quantity: string;
  /**
   * 주문 금액 (USD). 금액 기반 US 시장가 매수 주문에만 해당. 그 외 null
   */
  orderAmount?: string | null;
  currency: Currency;
  /**
   * 주문 시간 (ISO 8601, KST)
   */
  orderedAt: string;
  /**
   * 취소 시간 (ISO 8601, KST). 해당 없으면 null
   */
  canceledAt?: string | null;
  /**
   * 체결 결과. 체결 내역이 없으면 filledQuantity=0
   */
  execution: OrderExecution;
};

export type OrderExecution = {
  /**
   * 체결 수량
   */
  filledQuantity: string;
  /**
   * 평균 체결 가격 (native currency). 부분 체결 시 체결된 건의 평균, 미체결 시 null
   */
  averageFilledPrice: string | null;
  /**
   * 총 체결 금액 (native currency)
   */
  filledAmount: string | null;
  /**
   * 총 체결 수수료 (native currency)
   */
  commission: string | null;
  /**
   * 총 체결 세금 (native currency)
   */
  tax: string | null;
  /**
   * 최종 체결 시간 (ISO 8601, KST)
   */
  filledAt: string | null;
  /**
   * 결제 예정일 (YYYY-MM-DD, KST 기준). 미결제 시 null
   */
  settlementDate: string | null;
};

/**
 * 주문 상태.
 * - `PENDING`: 체결 대기. 주문이 접수되어 체결을 대기 중인 상태
 * - `PENDING_CANCEL`: 취소 대기. 취소 요청이 접수되어 브로커 응답을 대기 중인 상태
 * - `PENDING_REPLACE`: 정정 대기. 정정 요청이 접수되어 브로커 응답을 대기 중인 상태
 * - `PARTIAL_FILLED`: 부분 체결. 주문 수량 중 일부만 체결된 상태
 * - `FILLED`: 체결 완료. 주문 수량이 전량 체결된 상태
 * - `CANCELED`: 취소 완료. execution.filledQuantity를 통해 부분 체결 여부를 확인할 수 있음
 * - `REJECTED`: 거부됨. 브로커가 주문을 거부한 상태. execution.filledQuantity를 통해 부분 체결 여부를 확인할 수 있음
 * - `CANCEL_REJECTED`: 취소 거부. 브로커가 취소 요청을 거부한 경우 별도 주문 레코드로 생성됨. 원주문은 이전 상태로 복귀함
 * - `REPLACE_REJECTED`: 정정 거부. 브로커가 정정 요청을 거부한 경우 별도 주문 레코드로 생성됨. 원주문은 이전 상태로 복귀함
 * - `REPLACED`: 정정됨. 정정 요청이 수락되어 원주문이 대체된 상태. execution.filledQuantity를 통해 부분 체결 여부를 확인할 수 있음
 *
 * 클라이언트는 unknown code 를 허용하도록 구현해야 합니다.
 *
 */
export type OrderStatus =
  | 'PENDING'
  | 'PENDING_CANCEL'
  | 'PENDING_REPLACE'
  | 'PARTIAL_FILLED'
  | 'FILLED'
  | 'CANCELED'
  | 'REJECTED'
  | 'CANCEL_REJECTED'
  | 'REPLACE_REJECTED'
  | 'REPLACED';

export type BuyingPowerResponse = {
  currency: Currency;
  /**
   * 현금 기반 매수 가능 금액 (미수 미발생 기준).
   * 순수 현금으로 매수할 수 있는 금액.
   * KRW: 정수 (원 단위). USD: 소수점 포함 (달러 단위).
   *
   */
  cashBuyingPower: string;
};

export type SellableQuantityResponse = {
  /**
   * 판매 가능 수량.
   * KR: 정수 (주 단위). US: 소수점 포함 가능 (주 단위).
   *
   */
  sellableQuantity: string;
};

export type Commission = {
  marketCountry: MarketCountry;
  /**
   * 매매 수수료율 (소수 비율). 예: `0.00015` = 0.015%
   */
  commissionRate: string;
  /**
   * 수수료 적용 시작일 (YYYY-MM-DD, KST 기준). 해외주식은 null
   */
  startDate?: string | null;
  /**
   * 수수료 적용 종료일 (YYYY-MM-DD, KST 기준). 무기한 적용 시 null
   */
  endDate?: string | null;
};

/**
 * 거래내역 페이징 응답.
 * 조회 조건에 맞는 미결제 내역을 먼저 반환하고, 각 그룹 안에서는 해당 내역의 정렬 기준 시각이 최신인 순서로 정렬합니다.
 * 미결제의 정렬 기준은 국내주식 합산 내역의 첫 체결시각, 미국 주식 주문시각, 미국 옵션·채권 체결시각입니다.
 * 결제 완료 내역은 거래 처리시각 기준입니다. 매매는 결제 처리시각이며, 주문·체결시각과 다릅니다.
 * 국내주식은 미결제 한 건이 결제 후 여러 건의 결제 내역으로 바뀔 수 있습니다.
 * 반환 건수가 `limit`보다 적거나 0건이어도 다음 페이지가 있을 수 있으므로 `hasNext`로 종료 여부를 확인하세요.
 * 다음 페이지가 있으면 `nextCursor` 에 커서가, `hasNext` 에 `true` 가 내려옵니다.
 *
 */
export type PaginatedTransactionResponse = {
  /**
   * 거래 목록. 조건에 맞는 미결제 내역을 먼저 반환하며, 각 그룹 안에서는 정렬 기준 시각의 최신순입니다.
   */
  transactions: Array<Transaction>;
  /**
   * 다음 페이지 커서. 다음 페이지가 없으면 null입니다. 값의 길이와 내부 구조에 의존하지 말고 그대로 전달하세요. 문서 예시의 커서는 실제 요청에 사용할 수 없는 가상 값입니다.
   */
  nextCursor: string | null;
  /**
   * 다음 페이지 존재 여부
   */
  hasNext: boolean;
};

/**
 * 모든 금액(`filledPrice`·`amount`·`commission`·`tax`·`netAmount`)은 `currency` 통화이며 부호(+/−)가 없습니다.
 * 일반 거래의 금액 방향은 `transactionType`으로 구분합니다.
 * `isCancellation=true`이면 취소 거래입니다. `transactionType`은 취소 대상 거래(원거래)의 유형을 유지합니다.
 * 예를 들어 입금(`DEPOSIT`)을 취소한 내역은 `DEPOSIT`으로 표시되지만, 취소 금액은 계좌에서 빠져나갑니다.
 * 원거래는 목록에 표시되지 않고, 취소 거래만 표시됩니다. 따라서 거래 금액을 합산한 값이 해당 기간의 실제 계좌 잔액 변화와 일치하지 않을 수 있습니다.
 * 옵션·채권 거래도 같은 `transactionType` 으로 나오며 상품은 `assetClass` 로 구분합니다.
 *
 */
export type Transaction = {
  transactionType: TransactionType;
  /**
   * 거래가 속한 시장.
   * 종목 거래는 거래된 시장입니다. 현금·환전 거래는 통화가 `KRW`이면 `KR`, `USD`이면 `US`입니다.
   * 환전 한 건은 `KR` 거래와 `US` 거래, 두 건으로 나뉩니다.
   *
   */
  marketCountry: MarketCountry;
  /**
   * 이 거래의 모든 금액이 표시된 통화. `KR` 거래는 `KRW`, `US` 거래는 `USD`
   */
  currency: Currency;
  /**
   * 종목 심볼. 주식·옵션 거래에 제공하며, 주식 심볼을 확인할 수 없으면 null입니다.
   * - 주식(`assetClass=STOCK`): `GET /api/v1/stocks/{symbol}` 등 다른 API 에 그대로 쓸 수 있는 심볼 (KRX 6자리 종목코드, US 티커)
   * - 옵션(`assetClass=OPTION`): OCC 옵션 심볼 (기초자산 + 만기 `YYMMDD` + `C`/`P` + 행사가 8자리, 예 `AAPL261218C00150000`).
   * 옵션 계약 식별자이므로 다른 API 의 `symbol` 로 넣을 수 없습니다. `assetClass` 를 먼저 확인하세요.
   * - 채권(`assetClass=BOND`): 심볼이 없어 null. `isinCode` 로 식별합니다.
   * - 현금 거래(`assetClass` 가 null): null
   *
   */
  symbol: string | null;
  /**
   * 거래 상품을 구분하는 값입니다. 종목과 관련된 거래(매매·입출고·배당, 채권 이자·만기·이자 세금)면 유형과 무관하게 채우고,
   * 종목과 관련 없는 현금 거래(은행 입출금·환전·수수료 등)는 null 입니다.
   * 거래 시장은 `marketCountry` 가 나타냅니다.
   *
   */
  assetClass: AssetClass | null;
  /**
   * 국제증권식별번호 (ISO 6166). 주식·채권 거래에 채웁니다. 옵션은 ISIN 이 없고 현금 거래는 종목이 없어 null 입니다.
   * 거래 시점의 ISIN 이므로, 국내 종목의 액면분할·병합 이후에는 `GET /api/v1/stocks/{symbol}` 의 현재 값과 다를 수 있습니다.
   * 채권은 `symbol` 이 없어 이 값이 유일한 식별자입니다.
   *
   */
  isinCode: string | null;
  /**
   * 수량. `BUY`·`SELL`·`SECURITIES_TRANSFER_IN`·`SECURITIES_TRANSFER_OUT` 에 제공하며 그 외는 null 입니다.
   * 옵션은 계약 수, 채권은 채권 개수입니다.
   * `DIVIDEND` 는 null 입니다. 주식배당은 `SECURITIES_TRANSFER_IN` 으로 나오며 수량이 있습니다.
   *
   */
  quantity: string | null;
  /**
   * 매매 단가. `BUY`·`SELL`에 제공하며 그 외는 null입니다.
   * 국내주식 미결제(주문일·종목·매매방향별 합산)와 미국 주식 미결제(주문별 체결 누계)는 null 입니다.
   * 국내주식 결제 완료 내역과 미국 옵션·채권은 해당 내역의 체결단가를 제공합니다. 미국 주식 결제 완료 내역은 주문별 평균 체결단가를 제공합니다.
   * 단가를 확인할 수 없으면 null입니다. 거래내역 한 건이 개별 체결 한 건을 의미하지는 않습니다.
   * 옵션은 주당 프리미엄이며 1계약 = 100주이므로 `amount = filledPrice × quantity × 100` 입니다.
   * 채권은 경과이자를 포함한 채권 1개당 달러 가격입니다. 액면 100 기준 호가가 아니며, `amount = filledPrice × quantity` 입니다.
   *
   */
  filledPrice: string | null;
  /**
   * `currency` 통화 기준 거래금액. 합산 내역은 거래금액의 합계를 제공하며, 단가가 null일 수 있으므로 단가와 수량으로 재계산하지 않습니다.
   * 증권 입출고(`SECURITIES_TRANSFER_IN`·`SECURITIES_TRANSFER_OUT`)는 null 입니다.
   *
   */
  amount: string | null;
  /**
   * 수수료. 입출고·환전을 포함한 모든 유형에서 해당 거래의 금액을 제공하며, 값이 없으면 `"0"`입니다.
   */
  commission: string;
  /**
   * 해당 거래에 기록된 세금 합계. 값이 없으면 `"0"`입니다. 미국 채권 이자 입금의 세금은 `"0"`이며, 별도로 출금되는 원화 세금은 `WITHDRAWAL` 거래로 제공합니다. 이 경우 `amount`와 `tax`에 같은 세액이 표시될 수 있으며, `amount`에서 `tax`를 다시 차감하지 않습니다.
   */
  tax: string;
  /**
   * 수수료와 세금을 반영한 정산 금액입니다. 결제 완료 내역은 정산된 금액이며, 미결제 내역은 결제 전에 계산된 금액입니다.
   * 부호 없이 절대값으로 제공합니다. 취소 여부에 따른 금액 방향은 `isCancellation` 설명을 참고하세요.
   * 상품별 정산 규칙과 반올림 때문에 `amount`·`commission`·`tax`로 직접 계산한 값과 다를 수 있으므로, 계산하지 말고 이 값을 사용합니다.
   * 예수금 변동과 같지 않을 수 있습니다.
   * 증권 입출고(`SECURITIES_TRANSFER_IN`·`SECURITIES_TRANSFER_OUT`)는 null 입니다.
   *
   * 일반 거래(`isCancellation=false`)의 현금 방향은 다음과 같습니다.
   * - 유입: `SELL`, `DEPOSIT`, `EXCHANGE_IN`, `DIVIDEND`, `INTEREST`
   * - 유출: `BUY`, `WITHDRAWAL`, `EXCHANGE_OUT`, `FEE`
   *
   */
  netAmount: string | null;
  /**
   * 해당 거래의 환율 (1 USD당 KRW). `currency`가 `USD`인 결제 완료 거래에 제공하며, 값이 없으면 null입니다. 증권 입출고는 null입니다.
   * 미결제는 상품과 무관하게 null입니다. `KRW` 거래는 환전을 포함해 null입니다.
   * 환전 한 건의 환율은 `USD` 쪽 거래에서 확인합니다.
   *
   */
  exchangeRate: string | null;
  /**
   * KST 기준 결제일 (YYYY-MM-DD). 모든 거래에 제공합니다.
   * 결제된 매매는 결제일, 그 외 결제 완료 내역은 거래가 처리된 날짜이며 미결제 거래는 예상 결제일입니다. 미국 거래는 현지 결제일과 다를 수 있습니다.
   * 결제 여부는 날짜가 미래인지로 추정하지 말고 `settled`로 확인합니다.
   * 미결제 상태로 나오는 거래는 매매(`BUY`·`SELL`)뿐이며, 입출금·환전·배당·이자 등은 항상 결제된 상태로 조회됩니다.
   *
   */
  settlementDate: string;
  /**
   * 결제 완료 여부. 미결제는 false이며, 예상 결제일이 오늘 또는 과거여도 미결제일 수 있습니다.
   */
  settled: boolean;
  /**
   * 결제 완료 내역의 거래 처리일시(KST, +09:00). 매매는 결제 처리시각이며 주문시각이나 체결시각이 아닙니다.
   * 국내 취소거래는 취소 시점입니다. 미결제는 null입니다.
   * 조회 기간은 이 시각이 아닌 settlementDate 기준입니다.
   *
   */
  transactionTime: string | null;
  /**
   * 국내 거래의 취소 여부. true이면 거래를 취소한 내역이며, 원거래는 목록에서 제외됩니다.
   * 취소 내역의 거래 유형은 원래 유형을 유지합니다. 입금(`DEPOSIT`) 취소는 계좌에서 금액이 빠져나가며, 출금(`WITHDRAWAL`) 취소는 계좌로 금액이 돌아옵니다.
   * 거래를 취소하는 대신 반대 방향의 새 거래로 처리한 경우에는 false이며, 기존 거래와 새 거래가 함께 조회됩니다.
   * 모든 취소 방식을 나타내는 값은 아닙니다.
   *
   */
  isCancellation: boolean;
};

/**
 * 거래 유형. 요청 `transactionTypes` 와 같은 값 체계입니다.
 * 매수·매도는 미결제와 결제 완료 내역을 모두 포함하며, 결제 완료 여부는 `settled`로 구분합니다.
 * - `BUY`: 매수
 * - `SELL`: 매도
 * - `SECURITIES_TRANSFER_IN`: 증권 입고 (타사 이관, 주식배당 등)
 * - `SECURITIES_TRANSFER_OUT`: 증권 출고 (타사 이관, 옵션 만기 청산 등)
 * - `DEPOSIT`: 현금 입금 (은행 이체, 채권 만기 원리금 등)
 * - `WITHDRAWAL`: 현금 출금 (은행 이체, 채권 이자 세금 등)
 * - `EXCHANGE_IN`: 환전으로 받은 통화의 입금
 * - `EXCHANGE_OUT`: 환전으로 낸 통화의 출금
 * - `DIVIDEND`: 배당금 입금
 * - `INTEREST`: 이자 입금 (예탁금이용료, 채권 이자)
 * - `FEE`: 수수료 출금(외화보관수수료 등). 매매 수수료는 별도 거래가 아닌 매매 거래의 `commission`에 포함됩니다.
 *
 * 옵션·채권 거래도 위 유형으로 나오며 상품은 `assetClass` 로 구분합니다.
 *
 * 클라이언트는 unknown enum 값을 허용하도록 구현해야 합니다.
 *
 */
export type TransactionType =
  | 'BUY'
  | 'SELL'
  | 'SECURITIES_TRANSFER_IN'
  | 'SECURITIES_TRANSFER_OUT'
  | 'DEPOSIT'
  | 'WITHDRAWAL'
  | 'EXCHANGE_IN'
  | 'EXCHANGE_OUT'
  | 'DIVIDEND'
  | 'INTEREST'
  | 'FEE';

/**
 * 거래 상품군.
 * - `STOCK`: 주식. ETF·리츠·ETN 은 주식처럼 거래되므로 `STOCK` 이며, 세부 분류는 `GET /api/v1/stocks/{symbol}` 의 `securityType` 으로 확인합니다.
 * - `BOND`: 채권. `symbol` 은 null 이고 `isinCode` 로 식별합니다.
 * - `OPTION`: 옵션. `symbol` 은 OCC 옵션 심볼이며 `isinCode` 는 null 입니다.
 *
 * 클라이언트는 unknown enum 값을 허용하도록 구현해야 합니다.
 *
 */
export type AssetClass = 'STOCK' | 'BOND' | 'OPTION';

